/* GSVHIT ($96A1) - DRAW THE HIT ON THE WHOLE NEW GAUGE
 */
void gsvhit(void)
{
    CK(0x96A1);
    B = M8(S_GAS);                                   /* L96A1  VIEW NEW CURRENT GAS VALUE */
    B = (uint8_t)(B << 1);                           /* L96A3 */
    X = TGCLR;                                       /* L96A4 */
    D = rd16((uint16_t)(X + (int8_t)B));             /* L96A7  GET CORRECT COLOR */
    wr16(Y, D);                                      /* L96A9 */
    Y = (uint16_t)(Y + 2);
    B = M8(S_GAS);                                   /* L96AB  VIEW NEW CURRENT GAS VALUE */
    B = (uint8_t)(B << 1);                           /* L96AD */
    X = TGALL;                                       /* L96AE  DRAW ALL OF THE GAUGE */
    U = rd16((uint16_t)(X + (int8_t)B));             /* L96B1 */
    wr16(Y, U);                                      /* L96B3 */
    Y = (uint16_t)(Y + 2);
    CYC(51);
    RTS;                                             /* L96B5 */
}

