/* ADUSCR ($9810) - ADD IT IN
 * Condition codes out: C.
 */
void aduscr(void)
{
    CK(0x9810);
    A = rd8((uint16_t)(U + 2));                      /* L9810 */
    M8(SC_ADD+2) = A;                                /* L9812  DISPLAY OUR NEW ADDITION */
    A = add8(A, M8(S_SC21));                         /* L9815 */
    daa_a();                                         /* L9817 */
    M8(S_SC21) = A;                                  /* L9818 */
    A = rd8((uint16_t)(U + 1));                      /* L981A */
    M8(SC_ADD+1) = A;                                /* L981C */
    A = adc8(A, M8(S_SC43));                         /* L981F */
    daa_a();                                         /* L9821 */
    M8(S_SC43) = A;                                  /* L9822 */
    A = rd8(U);                                      /* L9824 */
    M8(SC_ADD+0) = A;                                /* L9826 */
    A = adc8(A, M8(S_SC65));                         /* L9829 */
    daa_a();                                         /* L982B */
    M8(S_SC65) = A;                                  /* L982C */
    A = M8(S_SC87);                                  /* L982E */
    A = adc8(A, 0x00);                               /* L9830 */
    daa_a();                                         /* L9832 */
    M8(S_SC87) = A;                                  /* L9833 */
    A = 0xFF;                                        /* L9835 */
    M8(SC_ADT) = A;                                  /* L9837  NEW TIMER FOR NEW ADDITION */
    CYC(83);
    RTS;                                             /* L983A */
}
